#include "aodv.h"
#include <string.h>
#include <stdlib.h>
#define ROUTE_MS 3000u
#define SEEN_MS 5000u
#define PENDING_MS 3000u
static uint32_t get32(const uint8_t*p){return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
static void put32(uint8_t*p,uint32_t x){p[0]=(uint8_t)x;p[1]=(uint8_t)(x>>8);p[2]=(uint8_t)(x>>16);p[3]=(uint8_t)(x>>24);}
/* RFC serial arithmetic; exact half-range is deliberately unordered. */
static int newer(uint32_t a,uint32_t b){uint32_t d=a-b;return d!=0&&d<0x80000000u;}
static void frame(uint8_t*b,int type,int len,int ttl,int src,int dst,int hops,uint32_t boot,uint32_t seq,uint32_t req,uint32_t dseq,uint32_t oseq,int known){memset(b,0,MA_HEADER);b[0]=MA_MAGIC;b[1]=MA_VERSION;b[2]=(uint8_t)type;b[3]=(uint8_t)len;b[4]=(uint8_t)ttl;b[5]=(uint8_t)src;b[6]=(uint8_t)dst;b[7]=(uint8_t)hops;put32(b+8,boot);put32(b+12,seq);put32(b+16,req);put32(b+20,dseq);put32(b+24,oseq);b[28]=(uint8_t)known;}
static int qpush(ma_node*n,const uint8_t*b,int next){ma_tx*x;if(n->qn==MA_TXQ){n->overflow++;n->tx_overflow++;return -1;}x=&n->tx[(n->qh+n->qn)%MA_TXQ];x->len=b[3];x->next=(uint8_t)next;x->type=b[2];memcpy(x->data,b,x->len);n->qn++;if(n->qn>n->tx_high)n->tx_high=n->qn;return 0;}
static void ev(ma_node*n,unsigned type,unsigned why,unsigned src,uint32_t boot,uint32_t seq,unsigned dst,uint32_t req,const uint8_t*data,unsigned len){ma_event*x;if(n->en==MA_EVENTS){n->event_overflow++;return;}x=&n->events[(n->eh+n->en)%MA_EVENTS];x->v[0]=type;x->v[1]=why;x->v[2]=src;x->v[3]=boot;x->v[4]=seq;x->v[5]=dst;x->v[6]=req;x->v[7]=len;if(len)memcpy(x->payload,data,len);n->en++;}
static int route_update(ma_node*n,unsigned dst,unsigned next,unsigned hops,uint32_t seq,int known,uint64_t t){ma_route*r;if(dst>=MA_NODES||next>=MA_NODES||dst==n->id||hops==0||hops>32)return 0;r=&n->route[dst];if(!r->valid || (known&&(!r->known||newer(seq,r->seq))) || (known==r->known&&(!known||seq==r->seq)&&hops<r->hops)){if(r->known&&known&&newer(r->seq,seq))return 0;if(r->known&&!known)return 0;r->valid=1;r->known=(uint8_t)known;r->seq=seq;r->next=(uint8_t)next;r->hops=(uint8_t)hops;r->expires=t+ROUTE_MS;return 1;}if(r->valid&&r->next==next&&r->known==known&&(!known||r->seq==seq))r->expires=t+ROUTE_MS;return 0;}
static int seen_bitmap(ma_node*n,unsigned o,uint32_t boot,uint32_t id,uint64_t t){unsigned i,slot=MA_SEEN;ma_seen*s;uint32_t delta,back;for(i=0;i<MA_SEEN;i++){s=&n->seen[i];if(s->used&&s->until>t&&s->origin==o&&s->boot==boot){delta=id-s->id;if(delta==0)return 1;if(delta<0x80000000u){s->bitmap=delta>=64?1u:(s->bitmap<<delta)|1u;s->id=id;s->until=t+SEEN_MS;return 0;}back=s->id-id;if(back>=64){n->seen_outside_window++;return 1;}if(s->bitmap&((uint64_t)1<<back))return 1;s->bitmap|=(uint64_t)1<<back;s->until=t+SEEN_MS;return 0;}if((!s->used||s->until<=t)&&slot==MA_SEEN)slot=i;}if(slot==MA_SEEN){n->overflow++;n->seen_overflow++;return -1;}n->seen[slot]=(ma_seen){1,(uint8_t)o,boot,id,t+SEEN_MS,1};return 0;}
static int seen_add(ma_node*n,unsigned o,uint32_t boot,uint32_t id,uint64_t t){unsigned i,freeidx=MA_SEEN;if(n->policy&8)return seen_bitmap(n,o,boot,id,t);for(i=0;i<MA_SEEN;i++){ma_seen*s=&n->seen[i];if(s->used&&s->until>t&&s->origin==o&&s->boot==boot&&s->id==id)return 1;if((!s->used||s->until<=t)&&freeidx==MA_SEEN)freeidx=i;}if(freeidx==MA_SEEN){n->overflow++;n->seen_overflow++;return -1;}n->seen[freeidx]=(ma_seen){1,(uint8_t)o,boot,id,t+SEEN_MS,0};return 0;}
static int issue(ma_node*n,unsigned dst,uint64_t t){uint8_t b[MA_HEADER];ma_discovery*d=&n->find[dst];ma_route*r=&n->route[dst];if(!d->active){d->active=1;d->ttl=2;d->attempts=0;}if(d->attempts>=4){d->active=0;n->denied++;return -1;}if(t-n->rreq_window>=1000){n->rreq_window=t;n->rreq_count=0;}if((n->policy&32)&&t-n->pressure_window>=2000)n->pressure_active=0;if(n->rreq_count>=(((n->policy&32)&&n->pressure_active)?3:10)){d->deadline=n->rreq_window+1000;d->deferred=1;return 0;}d->deferred=0;n->rreq_count++;n->own_seq++;n->rreq_id++;d->attempts++;if(seen_add(n,n->id,n->boot,n->rreq_id,t)!=0){d->active=0;return -1;}frame(b,MA_RREQ,MA_HEADER,d->ttl,n->id,dst,0,n->boot,0,n->rreq_id,r->seq,n->own_seq,r->known);if(qpush(n,b,MA_BROADCAST)){d->active=0;return -1;}d->deadline=t+400u+80u*d->ttl;return 0;}
static int send_data(ma_node*n,unsigned dst,unsigned src,uint32_t boot,uint32_t seq,const uint8_t*data,unsigned len,unsigned ttl,uint64_t t){uint8_t b[MA_MTU];ma_route*r=&n->route[dst];if(!r->valid||r->expires<=t)return -1;frame(b,MA_DATA,MA_HEADER+len,ttl,src,dst,0,boot,seq,0,0,0,0);memcpy(b+MA_HEADER,data,len);if(qpush(n,b,r->next))return -1;r->expires=t+ROUTE_MS;return 0;}
static void flush(ma_node*n,unsigned dst,uint64_t t){unsigned i;for(i=0;i<MA_PENDING;i++){ma_pending*p=&n->pending[i];if(p->used&&p->dst==dst){if(p->until>t&&send_data(n,dst,n->id,n->boot,p->seq,p->data,p->len,32,t)==0)p->used=0;}}}
void ma_init(ma_node*n,unsigned id,unsigned policy){memset(n,0,sizeof(*n));n->id=(uint8_t)id;n->boot=id+1;n->policy=(uint8_t)policy;n->peer_used[0]=1;n->peer_id[0]=MA_BROADCAST;}
int ma_submit(ma_node*n,unsigned dst,uint32_t seq,const uint8_t*b,unsigned len,uint64_t t){unsigned i,count=0;if(dst>=MA_NODES||dst==n->id||len>160||(!b&&len)){n->rejected++;return -1;}if(n->route[dst].valid&&n->route[dst].expires>t)return send_data(n,dst,n->id,n->boot,seq,b,len,32,t);for(i=0;i<MA_PENDING;i++)if(n->pending[i].used)count++;if(count>=MA_PENDING){n->rejected++;return -1;}for(i=0;i<MA_PENDING;i++)if(!n->pending[i].used){ma_pending*p=&n->pending[i];p->used=1;p->dst=(uint8_t)dst;p->seq=seq;p->len=(uint8_t)len;p->until=t+PENDING_MS;memcpy(p->data,b,len);if(count+1>n->pending_high)n->pending_high=(uint8_t)(count+1);if(!n->find[dst].active)issue(n,dst,t);return 0;}return -1;}
void ma_tick(ma_node*n,uint64_t t){unsigned i;for(i=0;i<MA_NODES;i++){ma_route*r=&n->route[i];ma_discovery*d=&n->find[i];if(r->valid&&r->expires<=t)r->valid=0;if(d->active&&d->deadline<=t){if(d->deferred){issue(n,i,t);}else{if(d->ttl<16)d->ttl*=2;issue(n,i,t);}}}for(i=0;i<MA_PENDING;i++){ma_pending*p=&n->pending[i];if(p->used&&p->until<=t){ev(n,7,1,n->id,n->boot,p->seq,p->dst,0,0,0);p->used=0;}}}
int ma_receive(ma_node*n,unsigned prev,const uint8_t*b,unsigned len,uint64_t t){unsigned typ,ttl,src,dst,hops;uint32_t boot,seq,req,dseq,oseq;uint8_t out[MA_MTU];ma_route*r;if(!b||len<MA_HEADER||len>MA_MTU||b[0]!=MA_MAGIC||b[1]!=MA_VERSION||b[3]!=len||prev>=MA_NODES||b[5]>=MA_NODES||b[6]>=MA_NODES||b[4]==0)return -1;typ=b[2];ttl=b[4];src=b[5];dst=b[6];hops=b[7];boot=get32(b+8);seq=get32(b+12);req=get32(b+16);dseq=get32(b+20);oseq=get32(b+24);if((typ!=MA_DATA&&len!=MA_HEADER)||hops>=32)return -1;
 if(typ==MA_RREQ){int s;n->rreq_rx++;if(n->policy&4){if(t-n->pressure_window>=1000){n->pressure_active=(uint8_t)(t-n->pressure_window<2000&&n->pressure_duplicates>=40);n->pressure_duplicates=0;n->pressure_window=t;}}s=seen_add(n,src,boot,req,t);if(s!=0){if(s>0){n->rreq_duplicates++;if(n->policy&4)n->pressure_duplicates++;}return s<0?-1:0;}route_update(n,src,prev,hops+1,oseq,1,t);if(n->id==dst){if(b[28]&&newer(dseq,n->own_seq))n->own_seq=dseq;r=&n->route[src];if(!r->valid)return -1;frame(out,MA_RREP,MA_HEADER,32,src,dst,0,boot,0,req,n->own_seq,0,1);n->rrep_dest++;return qpush(n,out,r->next);}if((n->policy&1)&&n->route[dst].valid&&n->route[dst].expires>t&&n->route[dst].known&&n->route[dst].next!=prev&&(!b[28]||!newer(dseq,n->route[dst].seq))){ma_route*reverse=&n->route[src];ma_route*known=&n->route[dst];if(reverse->valid){frame(out,MA_RREP,MA_HEADER,32,src,dst,known->hops,boot,0,req,known->seq,0,1);n->rrep_intermediate++;return qpush(n,out,reverse->next);}}if(ttl<=1)return 0;if((n->policy&2)||((n->policy&4)&&n->pressure_active)){if(t-n->forward_window>=1000){n->forward_window=t;n->forward_count=0;}if(n->forward_count>=8){n->forward_suppressed++;return 0;}n->forward_count++;}memcpy(out,b,len);out[4]--;out[7]++;if(n->route[dst].known&&(!out[28]||newer(n->route[dst].seq,get32(out+20)))){put32(out+20,n->route[dst].seq);out[28]=1;}n->rreq_forward++;return qpush(n,out,MA_BROADCAST);}
 if(typ==MA_RREP){int updated;if(n->id==src&&boot!=n->boot)return -1;updated=route_update(n,dst,prev,hops+1,dseq,1,t);if(n->id==src){if(updated){n->find[dst].active=0;flush(n,dst,t);}return 0;}if(!updated)return 0;r=&n->route[src];if(!r->valid||r->expires<=t||ttl<=1)return -1;memcpy(out,b,len);out[4]--;out[7]++;return qpush(n,out,r->next);}
 if(typ==MA_DATA){if(len-MA_HEADER>160)return -1;if(dst==n->id){ev(n,6,0,src,boot,seq,dst,0,b+MA_HEADER,len-MA_HEADER);return 0;}if(ttl<=1){ev(n,7,3,src,boot,seq,dst,0,0,0);return -1;}r=&n->route[dst];if(!r->valid||r->expires<=t){ev(n,7,2,src,boot,seq,dst,0,0,0);return -1;}memcpy(out,b,len);out[4]--;r->expires=t+ROUTE_MS;if(qpush(n,out,r->next)){ev(n,7,4,src,boot,seq,dst,0,0,0);return -1;}return 0;}
 if(typ==MA_RERR){r=&n->route[dst];if(r->valid&&r->next==prev&&(!r->known||(b[28]&&!newer(r->seq,dseq)))){r->valid=0;if(!r->known||newer(dseq,r->seq)){r->seq=dseq;r->known=1;}if(ttl>1){if(t-n->rerr_window>=1000){n->rerr_window=t;n->rerr_count=0;}if(n->rerr_count<10){n->rerr_count++;memcpy(out,b,len);out[4]--;qpush(n,out,MA_BROADCAST);}}}return 0;}return -1;}
int ma_next(ma_node*n,uint8_t*b,int*next,int*typ){ma_tx*x;if(n->has_inflight||!n->qn)return 0;x=&n->tx[n->qh];n->inflight=*x;n->has_inflight=1;memcpy(b,x->data,x->len);*next=x->next==MA_BROADCAST?-1:x->next;*typ=x->type;n->qh=(n->qh+1)%MA_TXQ;n->qn--;return x->len;}
void ma_result(ma_node*n,int ok,uint64_t t){unsigned i;uint8_t b[MA_HEADER];ma_tx*x=&n->inflight;if(!n->has_inflight)return;n->has_inflight=0;if(ok||x->next==MA_BROADCAST)return;if(x->type==MA_DATA)ev(n,7,5,x->data[5],get32(x->data+8),get32(x->data+12),x->data[6],0,0,0);for(i=0;i<MA_NODES;i++){ma_route*r=&n->route[i];if(r->valid&&r->next==x->next){r->valid=0;if(r->known)r->seq++;if(t-n->rerr_window>=1000){n->rerr_window=t;n->rerr_count=0;}if(n->rerr_count>=10)continue;n->rerr_count++;n->rerr_issued++;frame(b,MA_RERR,MA_HEADER,8,n->id,i,0,n->boot,0,0,r->seq,0,r->known);qpush(n,b,MA_BROADCAST);}}(void)t;}
int ma_event_next(ma_node*n,uint32_t*out,uint8_t*payload){ma_event*e;if(!n->en)return 0;e=&n->events[n->eh];memcpy(out,e->v,sizeof(e->v));if(e->v[7])memcpy(payload,e->payload,e->v[7]);n->eh=(n->eh+1)%MA_EVENTS;n->en--;return 1;}
int ma_peer(ma_node*n,int dst,uint64_t t){unsigned i,slot=20;uint64_t oldest=UINT64_MAX;uint8_t id=dst<0?MA_BROADCAST:(uint8_t)dst;for(i=0;i<20;i++)if(n->peer_used[i]&&n->peer_id[i]==id){n->peer_time[i]=t;return 0;}for(i=1;i<20;i++){if(!n->peer_used[i]){slot=i;break;}if(n->peer_time[i]<oldest){oldest=n->peer_time[i];slot=i;}}if(slot==20)return -1;i=n->peer_used[slot];n->peer_used[slot]=1;n->peer_id[slot]=id;n->peer_time[slot]=t;return i?1:0;}
